const assert = require('node:assert/strict');
const { ProfileService } = require('../.build/service');
const { parseProfile } = require('../.build/parser');

const profile = { displayName: 'before', tags: ['old'] };
const service = new ProfileService(profile);
const originalTags = profile.tags;
assert.equal(service.patch({}), profile);
assert.equal(profile.tags, originalTags);
assert.deepEqual(parseProfile({}), {
  displayName: { kind: 'keep' }, tags: { kind: 'keep' },
});

const input = Object.freeze({
  displayName: '  after  ', tags: Object.freeze([' one ', 'two']),
});
assert.deepEqual(service.patch(input), { displayName: 'after', tags: ['one', 'two'] });
assert.deepEqual(input, { displayName: '  after  ', tags: [' one ', 'two'] });
assert.notEqual(profile.tags, input.tags);
const callerTags = ['mutable'];
service.patch({ tags: callerTags });
callerTags.push('extra');
assert.deepEqual(profile.tags, ['mutable']);
profile.tags.push('stored only');
assert.deepEqual(callerTags, ['mutable', 'extra']);

assert.deepEqual(service.patch({ displayName: null }), {
  displayName: null, tags: ['mutable', 'stored only'],
});
assert.deepEqual(service.patch({ tags: null }), { displayName: null, tags: [] });
service.patch({ tags: ['tag'] });
assert.deepEqual(service.patch({ tags: [] }), { displayName: null, tags: [] });
const nullPrototype = Object.assign(Object.create(null), { displayName: ' null prototype ' });
assert.deepEqual(service.patch(nullPrototype), { displayName: 'null prototype', tags: [] });
assert.deepEqual(service.patch({ displayName: 'x'.repeat(40), tags: ['x'.repeat(12), 'a', 'b', 'c', 'd'] }), {
  displayName: 'x'.repeat(40), tags: ['x'.repeat(12), 'a', 'b', 'c', 'd'],
});

const invalidInputs = [
  null, undefined, [], 'name', 42, true, () => {}, new Date(),
  Object.create({ displayName: 'inherited' }),
  { unknown: true }, { [Symbol('unknown')]: true },
  Object.defineProperty({}, 'hidden', { value: true }),
  ...[undefined, 1, false, {}, [], '', '  ', 'x'.repeat(41)].map(displayName => ({ displayName })),
  ...[undefined, 1, false, {}, 'tag', [1], [null], [''], [' '],
    ['x'.repeat(13)], ['same', ' same '], ['a', 'b', 'c', 'd', 'e', 'f'],
    Array(1)].map(tags => ({ tags })),
  { displayName: 'valid', tags: ['duplicate', ' duplicate '] },
  { displayName: ' ', tags: ['valid'] },
  { displayName: 'valid', tags: ['valid'], extra: true },
];
for (const invalid of invalidInputs) {
  const before = { displayName: profile.displayName, tags: [...profile.tags] };
  const tags = profile.tags;
  assert.throws(() => service.patch(invalid), { name: 'Error', message: 'invalid profile' });
  assert.deepEqual(profile, before);
  assert.equal(profile.tags, tags);
}
console.log('PATCH contract checks passed');

